#include "gameplay.hpp"
#include <algorithm>
#include <cmath>
#include <cstring>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <limits>
namespace wf::gameplay {
static constexpr double pi=3.14159265358979323846;
double clamp(double v,double lo,double hi){return std::clamp(v,lo,hi);}
double lerp(double a,double b,double t){return a+(b-a)*t;}
static Vec3 interp(Vec3 a,Vec3 b,double t){return {lerp(a.x,b.x,t),lerp(a.y,b.y,t),lerp(a.z,b.z,t)};}
static double timeAt(double t,double end,bool loop){if(!std::isfinite(t)) throw std::invalid_argument("time"); if(loop&&end>0){t=std::fmod(t,end);if(t<0)t+=end;}return t;}
Vec3 interpolate(const Track& tr,double time){auto& k=tr.keys;if(k.empty())return {};for(size_t i=1;i<k.size();++i)if(k[i].time<=k[i-1].time)throw std::invalid_argument("unordered keys");time=timeAt(time,k.back().time,tr.loop);if(time<=k.front().time)return k.front().value;for(size_t i=1;i<k.size();++i)if(time<=k[i].time)return interp(k[i-1].value,k[i].value,(time-k[i-1].time)/(k[i].time-k[i-1].time));return k.back().value;}
Pose blend(const Pose&a,const Pose&b,double w){w=clamp(w,0,1);return {interp(a.position,b.position,w),interp(a.scale,b.scale,w),lerp(a.yaw,b.yaw,w)};}
Pose sample(const Clip& c,double time){auto& k=c.keys;if(k.empty())return {};for(size_t i=1;i<k.size();++i)if(k[i].time<=k[i-1].time)throw std::invalid_argument("unordered keys");time=timeAt(time,k.back().time,c.loop);if(time<=k.front().time)return k.front().pose;for(size_t i=1;i<k.size();++i)if(time<=k[i].time)return blend(k[i-1].pose,k[i].pose,(time-k[i-1].time)/(k[i].time-k[i-1].time));return k.back().pose;}
double envelope(const Envelope&e,double t,double held){if(t<0||!std::isfinite(t)||held<0)return 0;double a=std::max(0.,e.attack),d=std::max(0.,e.decay),r=std::max(0.,e.release),s=clamp(e.sustain,0,1);auto on=[&](double x){if(a>0&&x<a)return x/a;if(d>0&&x<a+d)return lerp(1,s,(x-a)/d);return s;};if(t<held)return on(t);double v=on(held);return r>0? v*clamp(1-(t-held)/r,0,1):0;}
double oscillator(double phase,int waveform){double f=phase-std::floor(phase);switch(waveform){case 0:return std::sin(2*pi*f);case 1:return f<.5?1:-1;case 2:return 2*f-1;case 3:return 1-4*std::abs(f-.5);default:throw std::invalid_argument("waveform");}}
std::vector<float> synthesize(const Note& n,const Envelope&e,int sr,int wave){if(sr<1000||sr>192000||n.hz<=0||n.hz>=sr/2||n.duration<0||n.duration>60||!std::isfinite(n.amplitude))throw std::invalid_argument("note");double total=n.duration+std::max(0.,e.release);std::vector<float> out(static_cast<size_t>(std::ceil(total*sr)));for(size_t i=0;i<out.size();++i){double t=double(i)/sr;out[i]=float(clamp(n.amplitude*envelope(e,t,n.duration)*oscillator(n.hz*t,wave),-1,1));}return out;}
std::vector<float> mix(const std::vector<std::vector<float>>& tracks){size_t n=0;for(auto&t:tracks)n=std::max(n,t.size());std::vector<float> o(n);for(auto&t:tracks)for(size_t i=0;i<t.size();++i)o[i]+=t[i];for(auto&v:o)v=float(clamp(v,-1,1));return o;}
std::vector<float> lowpass(const std::vector<float>& x,double cutoff,int sr){if(sr<=0||cutoff<=0||cutoff>=sr/2)throw std::invalid_argument("cutoff");double alpha=1-std::exp(-2*pi*cutoff/sr),v=0;std::vector<float> out;out.reserve(x.size());for(auto s:x){v+=alpha*(s-v);out.push_back(float(v));}return out;}
std::vector<float> delay(const std::vector<float>& x,int samples,double feedback){if(samples<=0||samples>1000000||feedback<0||feedback>=1)throw std::invalid_argument("delay");std::vector<float> out(x.size()+size_t(samples));for(size_t i=0;i<out.size();++i){double v=i<x.size()?x[i]:0;if(i>=size_t(samples))v+=feedback*out[i-samples];out[i]=float(clamp(v,-1,1));}return out;}
static void u16(std::ofstream&f,uint16_t v){char b[2]={char(v),char(v>>8)};f.write(b,2);}static void u32(std::ofstream&f,uint32_t v){for(int i=0;i<4;++i)f.put(char(v>>(8*i)));}
bool writeWav(const std::string& path,const std::vector<float>& x,int sr){if(sr<1000||sr>192000||x.size()>UINT32_MAX/2-22)return false;std::ofstream f(path,std::ios::binary);if(!f)return false;uint32_t bytes=uint32_t(x.size()*2);f.write("RIFF",4);u32(f,36+bytes);f.write("WAVEfmt ",8);u32(f,16);u16(f,1);u16(f,1);u32(f,uint32_t(sr));u32(f,uint32_t(sr*2));u16(f,2);u16(f,16);f.write("data",4);u32(f,bytes);for(float s:x){int v=int(std::lrint(clamp(std::isfinite(s)?s:0.,-1.,1.)*32767));u16(f,uint16_t(int16_t(v)));}return bool(f);}
std::vector<Instruction> compile(const std::string& source){std::istringstream in(source);std::string line;std::vector<Instruction> code;while(std::getline(in,line)){auto pos=line.find('#');if(pos!=std::string::npos)line.resize(pos);std::istringstream s(line);std::string op;if(!(s>>op))continue;Instruction i;if(op=="set")i.op=Instruction::Set;else if(op=="add")i.op=Instruction::Add;else if(op=="mul")i.op=Instruction::Mul;else if(op=="wait")i.op=Instruction::Wait;else if(op=="emit")i.op=Instruction::Emit;else if(op=="jlt")i.op=Instruction::JumpIfLess;else if(op=="stop")i.op=Instruction::Stop;else throw std::invalid_argument("unknown opcode");if(i.op==Instruction::Set||i.op==Instruction::Add||i.op==Instruction::Mul||i.op==Instruction::JumpIfLess){if(!(s>>i.slot>>i.value)||i.slot<0||i.slot>=16||!std::isfinite(i.value))throw std::invalid_argument("register/value");if(i.op==Instruction::JumpIfLess&&(!(s>>i.target)||i.target<0))throw std::invalid_argument("jump");}else if(i.op==Instruction::Wait||i.op==Instruction::Emit){if(!(s>>i.value)||!std::isfinite(i.value)||i.value<0|| (i.op==Instruction::Emit&&i.value>1000000))throw std::invalid_argument("operand");}std::string extra;if(s>>extra)throw std::invalid_argument("extra token");code.push_back(i);if(code.size()>4096)throw std::invalid_argument("too much code");}for(auto&i:code)if(i.op==Instruction::JumpIfLess&&size_t(i.target)>=code.size())throw std::invalid_argument("jump out of bounds");return code;}
void execute(VM&vm,const std::vector<Instruction>& code,double dt,int budget){if(dt<0||!std::isfinite(dt)||budget<=0)throw std::invalid_argument("step");if(vm.halted)return;if(vm.wait>0){vm.wait=std::max(0.,vm.wait-dt);if(vm.wait>0)return;}for(int steps=0;steps<budget;++steps){if(vm.pc>=code.size()){vm.halted=true;return;}auto i=code[vm.pc++];switch(i.op){case Instruction::Set:vm.registers[i.slot]=i.value;break;case Instruction::Add:vm.registers[i.slot]+=i.value;break;case Instruction::Mul:vm.registers[i.slot]*=i.value;break;case Instruction::Wait:vm.wait=i.value;return;case Instruction::Emit:vm.events.push_back(int(i.value));break;case Instruction::JumpIfLess:if(vm.registers[i.slot]<i.value)vm.pc=size_t(i.target);break;case Instruction::Stop:vm.halted=true;return;}}}
uint64_t fingerprint(const VM&vm){uint64_t h=14695981039346656037ull;auto mix=[&](uint64_t v){for(int i=0;i<8;++i){h^=(v>>(i*8))&255;h*=1099511628211ull;}};for(double d:vm.registers){uint64_t u;std::memcpy(&u,&d,8);mix(u);}mix(vm.pc);uint64_t w;std::memcpy(&w,&vm.wait,8);mix(w);mix(vm.halted);for(int e:vm.events)mix(uint64_t(e));return h;}
}
